c=mix(c,vec3(0.115,0.090,0.050),smoothstep(0.30,0.45,h));
c=mix(c,vec3(0.074,0.066,0.040),smoothstep(0.52,0.62,h));
c=mix(c,vec3(0.076,0.064,0.052),smoothstep(0.68,0.76,h));
c=mix(c,vec3(0.096,0.062,0.040),smoothstep(0.80,0.88,h));
return mix(c,vec3(0.034,0.026,0.020),smoothstep(0.93,0.97,h));
